<?= $this->extend('admin/admin_layout') ?>
<?= $this->section('content') ?>
<div class="mb-6"><h1 class="text-3xl font-bold tracking-[-.025em]">Adopter Management</h1><p class="text-slate-500">One record per adopter, with all of their active adoptions grouped together.</p></div>
<div class="mb-6 grid gap-6 md:grid-cols-4"><?php foreach ([['Total Adopters', count($adopters)], ['Fully Compliant', count(array_filter($adopters, fn($a)=>(int) $a['compliance_score']>=85))], ['Needs Attention', count(array_filter($adopters, fn($a)=>(int) $a['compliance_score']<85))], ['Overdue Visits', array_sum(array_column($adopters, 'overdue_visits'))]] as $s): ?><div class="card"><div class="text-2xl font-bold"><?= esc($s[1]) ?></div><div class="text-sm font-medium text-slate-500"><?= esc($s[0]) ?></div></div><?php endforeach; ?></div>
<div class="card overflow-x-auto p-0"><table class="min-w-[860px] w-full text-sm"><thead class="bg-slate-50 text-xs uppercase tracking-wider text-slate-500"><tr><th class="px-4 py-3 text-left">Adopter</th><th class="px-4 py-3 text-left">Active Adoptions</th><th class="px-4 py-3 text-left">Monitoring Score</th><th class="px-4 py-3 text-left">Next Check-in</th><th class="px-4 py-3 text-left">Flag</th><th class="px-4 py-3 text-right">Action</th></tr></thead><tbody><?php foreach ($adopters as $a): ?><tr class="border-t hover:bg-slate-50"><td class="px-4 py-3"><a class="font-semibold text-rescue-700 hover:underline" href="<?= site_url('admin/adopters/' . $a['id']) ?>"><?= esc($a['name']) ?></a><div class="text-xs text-slate-500"><?= esc($a['email']) ?></div></td><td class="px-4 py-3"><?php if (empty($a['adopted_cats'])): ?><span class="text-slate-400">None</span><?php else: ?><div class="flex flex-wrap gap-1.5"><?php foreach ($a['adopted_cats'] as $cat): ?><span class="rounded-full bg-rescue-50 px-2.5 py-1 text-xs font-semibold text-rescue-700"><?= esc($cat['animal_name']) ?></span><?php endforeach; ?></div><?php endif; ?></td><td class="px-4 py-3"><div class="h-2 w-28 rounded bg-slate-100"><div class="h-2 rounded bg-rescue-600" style="width:<?= esc(min(100, max(0, (int) $a['compliance_score']))) ?>%"></div></div><div class="mt-1 text-xs text-slate-600"><?= esc($a['compliance_score']) ?>% <span class="text-slate-400">monitoring</span></div></td><td class="px-4 py-3"><?= $a['next_check_in'] ? esc(date('M d, Y', strtotime($a['next_check_in']))) : '<span class="text-slate-400">—</span>' ?></td><td class="px-4 py-3"><?= statusBadge($a['flag'] ?: 'None') ?></td><td class="px-4 py-3 text-right"><a href="<?= site_url('admin/adopters/' . $a['id']) ?>" class="inline-flex items-center gap-1.5 rounded-lg border border-rescue-200 bg-rescue-50 px-3 py-2 text-xs font-semibold text-rescue-700 hover:bg-rescue-100"><i data-lucide="pencil" class="h-4 w-4"></i>Manage</a></td></tr><?php endforeach; ?></tbody></table><?php if (empty($adopters)): ?><div class="p-10 text-center text-sm text-slate-500">No adopter records yet.</div><?php endif; ?></div>
<?= $this->endSection() ?>
